const raw = $input.first().json.output || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
let parsed = JSON.parse(cleaned);

// Se l'AI ha avvolto l'array in {products: [...]}, estrai l'array
if (parsed && parsed.products && Array.isArray(parsed.products)) {
  parsed = parsed.products;
}
// Se è un singolo oggetto, incapsulalo in array
if (!Array.isArray(parsed)) {
  parsed = [parsed];
}
const dbItems = $('SELECT UNREAD MAILS').all();
const dbByCode = {};
const dbByName = {};
dbItems.forEach(function(item) {
  if (item.json.supplier_product_code) {
    dbByCode[item.json.supplier_product_code] = item.json;
  }
  if (item.json.NAME) {
    dbByName[item.json.NAME.toLowerCase()] = item.json;
  }
});
return parsed.map(function(p) {
  const code = p.supplier_product_code || '';
  const pname = (p.product_name || '').toLowerCase();
  const db = dbByCode[code] || dbByName[pname] || {};
  return {
    json: {
      status: p.status,
      supplier_product_code: p.supplier_product_code || db.supplier_product_code,
      product_name: p.product_name,
      confirmed_quantity: p.confirmed_quantity || db.ordered_quantity,
      total_price: p.total_price,
      batch_number: p.batch_number || null,
      alternative_product_name: p.alternative_product_name,
      alternative_product_code: p.alternative_product_code,
      delivery_date: p.delivery_date,
      order_id: db.order_id || null,
      product_id: db.product_id || null,
      supplier_id: db.supplier_id || null,
      price_per_unit: db.price_per_unit || null,
      ordered_unit: db.ordered_unit || null,
      ordered_quantity: db.ordered_quantity || null
    }
  };
});

